  // Local time: July 20, 2025, 10:44 am HST (Hawaii Standard Time = UTC-10)
  // Convert to UTC: 10:44 HST + 10 hours = 20:44 UTC
  const startDate = ee.Date('2025-07-20T20:44:00Z');
  const endDate = startDate.advance(1, 'minute'); // A very narrow window around the specific minute

  console.log('Analysis Area Geometry:', analysisArea.getInfo());
  console.log('Requested Start Date (UTC):', startDate.format('YYYY-MM-dd HH:mm:ss').getInfo());
  console.log('Requested End Date (UTC):', endDate.format('YYYY-MM-dd HH:mm:ss').getInfo());

